insert into portfolio.site_content (site_id, overview, front_desk, emergency_guidance, parking, loading_dock, deliveries, security_procedures, access, policies, updated_by) values
('25b420e7-1544-5cfd-9f7f-dd81420b6693', 'One Commerce Plaza is a 14-story Class A office tower in Uptown Charlotte with 24/7 concierge, a rooftop terrace, and on-site fitness center.', 'Front desk is staffed Monday-Friday, 7:00 AM-7:00 PM. After-hours access requires a building fob.', 'In case of emergency, use the nearest stairwell - elevators are disabled during fire alarms. Assembly point is the plaza across South Tryon Street.', 'Visitor parking is available on P2 and P3 with front desk validation. Monthly reserved spots available on request.', 'Loading dock is on the south side of the building, accessible from Church Street. Hours: 6:00 AM-4:00 PM Monday-Friday.', 'All deliveries must be scheduled with the front desk 24 hours in advance and routed through the loading dock.', 'Building access requires a fob after 7:00 PM and on weekends. Visitors must be escorted past the lobby turnstiles.', 'Tenant fobs grant access to their leased floor and shared amenities. Contact property management to add or remove credentials.', 'Quiet hours in shared amenity spaces are 9:00 PM-7:00 AM. Pets are not permitted in common areas.', '5b7bced6-8e6d-50c8-8328-0d9598fdf883')
insert into portfolio.site_contacts (site_id, label, person_name, role, phone, email, availability, is_emergency, sort_order) values
('25b420e7-1544-5cfd-9f7f-dd81420b6693', 'Property Manager', 'Jordan Mitchell', 'Property Manager', '(704) 555-0114', 'demo@cre.local', 'Mon-Fri, 8:00 AM-6:00 PM', false, 1),
('25b420e7-1544-5cfd-9f7f-dd81420b6693', 'Building Engineer', 'Casey Alvarez', 'Chief Engineer', '(704) 555-0128', 'manager2@cre.local', 'Mon-Fri, 6:00 AM-4:00 PM', false, 2),
('25b420e7-1544-5cfd-9f7f-dd81420b6693', 'After-Hours Security', 'SecureGuard Dispatch', 'Security', '(704) 555-0199', 'dispatch@secureguard.example.com', '24/7', true, 3);
insert into portfolio.site_faqs (site_id, question, answer, sort_order) values
('25b420e7-1544-5cfd-9f7f-dd81420b6693', 'What are the building hours?', 'The building is open Monday-Friday, 7:00 AM-7:00 PM. Tenants with fob access may enter 24/7.', 1),
('25b420e7-1544-5cfd-9f7f-dd81420b6693', 'How do I reserve a conference room?', 'Use the Reservations tab in the tenant portal to check availability and book Conference Center A.', 2),
('25b420e7-1544-5cfd-9f7f-dd81420b6693', 'Who do I contact for a maintenance issue?', 'Submit a service request through the tenant portal and the building engineering team will be dispatched.', 3);
